// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, TransposeOperation } from '@stdlib/types/blas';

/**
* Interface describing `dlagtm`.
*/
interface Routine {
	/**
	* Performs a matrix-matrix product of the form `B := α*op(A)*X + β*B` where `op(A)` is either `op(A) = A` or `op(A) = A^T`, `α` and `β` are scalars, and `A` is a tridiagonal matrix.
	*
	* @param order - storage layout
	* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
	* @param N - order of the tridiagonal matrix `A`
	* @param NRHS - number of right hand sides
	* @param alpha - scalar `alpha`
	* @param DL - sub-diagonal elements of `A`
	* @param D - diagonal elements of `A`
	* @param DU - super-diagonal elements of `A`
	* @param X - input matrix `X`
	* @param LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
	* @param beta - scalar `beta`
	* @param B - input/output matrix `B`
	* @param LDB - stride of the first dimension of `B` (a.k.a., leading dimension of the matrix `B`)
	* @returns `B`
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var DL = new Float64Array( [ 1.0, 1.0 ] );
	* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
	* var DU = new Float64Array( [ 1.0, 1.0 ] );
	* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
	* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
	*
	* dlagtm( 'column-major', 'no-transpose', 3, 1, 1.0, DL, D, DU, X, 3, 0.0, B, 3 );
	* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
	*/
	( order: Layout, trans: TransposeOperation, N: number, NRHS: number, alpha: number, DL: Float64Array, D: Float64Array, DU: Float64Array, X: Float64Array, LDX: number, beta: number, B: Float64Array, LDB: number ): Float64Array;

	/**
	* Performs a matrix-matrix product of the form `B := α*op(A)*X + β*B` where `op(A)` is either `op(A) = A` or `op(A) = A^T`, `α` and `β` are scalars, and `A` is a tridiagonal matrix, using alternative indexing semantics.
	*
	* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
	* @param N - order of the tridiagonal matrix `A`
	* @param NRHS - number of right hand sides
	* @param alpha - scalar `alpha`
	* @param DL - sub-diagonal elements of `A`
	* @param strideDL - stride length for `DL`
	* @param offsetDL - starting index of `DL`
	* @param D - diagonal elements of `A`
	* @param strideD - stride length for `D`
	* @param offsetD - starting index of `D`
	* @param DU - super-diagonal elements of `A`
	* @param strideDU - stride length for `DU`
	* @param offsetDU - starting index of `DU`
	* @param X - input matrix `X`
	* @param strideX1 - stride of the first dimension of `X`
	* @param strideX2 - stride of the second dimension of `X`
	* @param offsetX - starting index for `X`
	* @param beta - scalar `beta`
	* @param B - input/output matrix `B`
	* @param strideB1 - stride of the first dimension of `B`
	* @param strideB2 - stride of the second dimension of `B`
	* @param offsetB - starting index for `B`
	* @returns `B`
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var DL = new Float64Array( [ 1.0, 1.0 ] );
	* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
	* var DU = new Float64Array( [ 1.0, 1.0 ] );
	* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
	* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
	*
	* dlagtm.ndarray( 'no-transpose', 3, 1, 1.0, DL, 1, 0, D, 1, 0, DU, 1, 0, X, 1, 3, 0, 0.0, B, 1, 3, 0 );
	* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
	*/
	ndarray( trans: TransposeOperation, N: number, NRHS: number, alpha: number, DL: Float64Array, strideDL: number, offsetDL: number, D: Float64Array, strideD: number, offsetD: number, DU: Float64Array, strideDU: number, offsetDU: number, X: Float64Array, strideX1: number, strideX2: number, offsetX: number, beta: number, B: Float64Array, strideB1: number, strideB2: number, offsetB: number ): Float64Array;
}

/**
* Performs a matrix-matrix product of the form `B := α*op(A)*X + β*B` where `op(A)` is either `op(A) = A` or `op(A) = A^T`, `α` and `β` are scalars, and `A` is a tridiagonal matrix.
*
* @param order - storage layout
* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param N - order of the tridiagonal matrix `A`
* @param NRHS - number of right hand sides
* @param alpha - scalar `alpha`
* @param DL - sub-diagonal elements of `A`
* @param D - diagonal elements of `A`
* @param DU - super-diagonal elements of `A`
* @param X - input matrix `X`
* @param LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
* @param beta - scalar `beta`
* @param B - input/output matrix `B`
* @param LDB - stride of the first dimension of `B` (a.k.a., leading dimension of the matrix `B`)
* @returns `B`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var DL = new Float64Array( [ 1.0, 1.0 ] );
* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
* var DU = new Float64Array( [ 1.0, 1.0 ] );
* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dlagtm( 'column-major', 'no-transpose', 3, 1, 1.0, DL, D, DU, X, 3, 0.0, B, 3 );
* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var DL = new Float64Array( [ 1.0, 1.0 ] );
* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
* var DU = new Float64Array( [ 1.0, 1.0 ] );
* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dlagtm.ndarray( 'no-transpose', 3, 1, 1.0, DL, 1, 0, D, 1, 0, DU, 1, 0, X, 1, 3, 0, 0.0, B, 1, 3, 0 );
* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
*/
declare var dlagtm: Routine;


// EXPORTS //

export = dlagtm;
